<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { actualizarMotivo, crearMotivo, listarMotivos } from '../services/motivosExpediente'
import type { Motivo, Option } from '../interfaces/motivosExpediente.interface'
const rows=ref<Motivo[]>([]),tipos=ref<Option[]>([]),conceptos=ref<Option[]>([]),editing=ref<Motivo|null>(null),detail=ref<Motivo|null>(null),modal=ref(false),criterio=ref(''),tipo=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const defaults={motivo:'',descripcion:'',tipo_expediente_id:'',concepto_id:'',referido_a:'',estado_suministro:'',requiere_suministro:false,crea_contrato:false,requiere_contraste:false,verifica_deuda:false,quiebre_total:false,afecta_interes:false,crea_suministro:false,requiere_monto_reclamo:false,activo:true},form=reactive({...defaults})
const flags:[keyof Motivo,string][]=[['requiere_suministro','Requiere suministro'],['crea_contrato','Crea contrato'],['requiere_contraste','Requiere contraste'],['verifica_deuda','Verifica deuda'],['quiebre_total','Quiebre total'],['afecta_interes','Afecta interés'],['crea_suministro','Crea suministro'],['requiere_monto_reclamo','Requiere monto reclamado']]
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const r=await listarMotivos(criterio.value,tipo.value,p);rows.value=r.data;tipos.value=r.tipos_expediente;conceptos.value=r.conceptos;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=msg(e)}finally{loading.value=false}}
function open(x?:Motivo){editing.value=x||null;Object.assign(form,defaults,x?{...x,tipo_expediente_id:String(x.tipo_expediente_id),concepto_id:String(x.concepto_id)}:{});modal.value=true}
async function submit(){if(!form.tipo_expediente_id||!form.concepto_id||!form.motivo.trim()||!form.descripcion.trim()){error.value='Complete el tipo, flujo, motivo y descripción.';return}saving.value=true;error.value='';try{editing.value?await actualizarMotivo(editing.value.id,form):await crearMotivo(form);success.value=editing.value?'Motivo actualizado correctamente.':'Motivo registrado correctamente.';modal.value=false;await load(page.value)}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Motivos de expediente</nav><header class="hero"><div class="mark">ME</div><div><small>EVAN · CONFIGURACIÓN COMERCIAL</small><h1>Motivos de expediente</h1><p>Reglas de validación y efectos para solicitudes y reclamos.</p></div><strong>{{total}} motivos</strong><button @click="open()">+ Registrar motivo</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Motivo o descripción" @keyup.enter="load(1)"></label><label>Tipo de expediente<select v-model="tipo"><option value="">Todos</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando motivos…</div><div v-else-if="!rows.length" class="empty">No se encontraron motivos de expediente.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><span>{{x.tipo_expediente}}</span><em :class="{off:!x.activo}">{{x.activo?'Activo':'Inactivo'}}</em></header><h2>{{x.motivo}}</h2><p>{{x.descripcion}}</p><dl><div><dt>Flujo / concepto</dt><dd>{{x.concepto}}</dd></div><div><dt>Referido a</dt><dd>{{x.referido_a||'—'}}</dd></div></dl><div class="tags"><span v-for="f in flags.filter(([k])=>x[k])" :key="f[0]">{{f[1]}}</span></div><footer><button @click="detail=x">Ver reglas</button><button @click="open(x)">Modificar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div><small>{{detail.tipo_expediente}} · {{detail.concepto}}</small><h2>{{detail.motivo}}</h2><p>{{detail.descripcion}}</p></div><button @click="detail=null">×</button></header><h3>Reglas del expediente</h3><div class="rules"><div v-for="f in flags" :key="f[0]" :class="{on:detail[f[0]]}"><i>{{detail[f[0]]?'✓':'—'}}</i><span>{{f[1]}}</span></div></div><dl><div><dt>Estado que puede solicitar</dt><dd>{{detail.estado_suministro||'Sin restricción'}}</dd></div><div><dt>Referido a</dt><dd>{{detail.referido_a||'—'}}</dd></div></dl><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal wide" @submit.prevent="submit"><header><div><small>MOTIVO DE EXPEDIENTE</small><h2>{{editing?'Modificar motivo':'Registrar nuevo motivo'}}</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Tipo de expediente *<select v-model="form.tipo_expediente_id" required><option value="">Seleccione</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Flujo / concepto *<select v-model="form.concepto_id" required><option value="">Seleccione</option><option v-for="x in conceptos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Motivo *<input v-model.trim="form.motivo" maxlength="255" required></label><label>Referido a<input v-model.trim="form.referido_a" maxlength="2" placeholder="Ej. A1"></label></div><label>Descripción *<textarea v-model.trim="form.descripcion" maxlength="255" rows="3" required></textarea></label><div class="grid"><label>Estado del suministro que puede solicitar<select v-model="form.estado_suministro"><option value="">Sin restricción</option><option>Activo</option><option>Cortado</option><option>Levantado</option></select></label><label class="check"><input v-model="form.activo" type="checkbox"> Motivo activo</label></div><h3>Reglas y efectos</h3><div class="switches"><label v-for="f in flags" :key="f[0]" class="check"><input v-model="form[f[0] as keyof typeof form]" type="checkbox"> {{f[1]}}</label></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar motivo'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#267bbd;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.56rem}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.58rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:15px;border-top:3px solid var(--a);border-radius:9px;background:#fff}.cards header{display:flex;justify-content:space-between}.cards header span{color:var(--a);font-size:.5rem;font-weight:700}.cards em{padding:4px 7px;border-radius:9px;color:#26785b;background:#e9f8f1;font-size:.45rem;font-style:normal}.cards em.off{color:#92545a;background:#faeded}.cards h2{font-size:.66rem}.cards>article>p{min-height:38px;color:#748087;font-size:.51rem}.cards dl,.modal dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.cards dt,.modal dt{color:#89949a;font-size:.46rem}.cards dd,.modal dd{margin:2px 0;font-size:.5rem;font-weight:700}.tags{min-height:36px}.tags span{margin:2px;padding:3px 5px;display:inline-block;border-radius:5px;color:#52666f;background:#eef2f4;font-size:.43rem}.cards footer{margin-top:auto;display:flex;justify-content:flex-end}.cards footer button{border:0;color:var(--a);background:none;font-size:.49rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,700px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.wide{width:min(100%,850px)}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal h3{font-size:.62rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin:10px 0;font-size:.54rem}.grid,.switches{display:grid;grid-template-columns:1fr 1fr;gap:7px}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}.switches label{padding:8px;border-radius:6px;background:#f5f7f8}.rules{display:grid;grid-template-columns:1fr 1fr;gap:6px}.rules div{padding:8px;display:flex;gap:7px;color:#8b969b;background:#f5f7f8;font-size:.52rem}.rules div.on{color:#26785b;background:#e9f8f1}.modal dl div{padding:9px;background:#f7f8f9}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:520px){.cards,.grid,.switches,.rules{grid-template-columns:1fr}}
</style>
